namespace RecipeShare.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public List<string> Ingredients { get; set; } = [];
    public List<string> Steps { get; set; } = [];
    public List<int> Ratings { get; set; } = [];
    public double AverageRating => Ratings.Count > 0 ? Ratings.Average() : 0;
}

using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes =
    [
        new()
        {
            Id = 1,
            Title = "Classic Margherita Pizza",
            Category = "Italian",
            Description = "A simple and delicious traditional pizza with fresh mozzarella, basil, and tomato sauce.",
            Ingredients = ["Pizza dough", "San Marzano tomatoes", "Fresh mozzarella", "Fresh basil", "Olive oil", "Salt"],
            Steps =
            [
                "Preheat oven to 475°F (245°C) with a pizza stone inside.",
                "Stretch dough into a 12-inch round on a floured surface.",
                "Spread crushed tomatoes over the dough, leaving a 1-inch border.",
                "Tear mozzarella into pieces and distribute evenly.",
                "Drizzle with olive oil and season with salt.",
                "Bake for 10-12 minutes until crust is golden and cheese is bubbly.",
                "Top with fresh basil leaves and serve immediately."
            ],
            Ratings = [5, 4, 5, 5, 4]
        },
        new()
        {
            Id = 2,
            Title = "Chicken Tikka Masala",
            Category = "Indian",
            Description = "Tender chicken pieces in a creamy, spiced tomato-based sauce.",
            Ingredients = ["Chicken breast", "Yogurt", "Garam masala", "Cumin", "Tomato sauce", "Heavy cream", "Garlic", "Ginger", "Onion"],
            Steps =
            [
                "Marinate chicken in yogurt, garam masala, and cumin for at least 1 hour.",
                "Grill or broil chicken until charred and cooked through.",
                "Sauté onion, garlic, and ginger in oil until soft.",
                "Add tomato sauce and remaining spices, simmer for 15 minutes.",
                "Stir in heavy cream and add the cooked chicken.",
                "Simmer for 10 more minutes and serve with basmati rice."
            ],
            Ratings = [5, 5, 4]
        },
        new()
        {
            Id = 3,
            Title = "Beef Tacos",
            Category = "Mexican",
            Description = "Seasoned ground beef tacos with fresh toppings.",
            Ingredients = ["Ground beef", "Taco shells", "Lettuce", "Tomato", "Cheddar cheese", "Sour cream", "Taco seasoning", "Onion"],
            Steps =
            [
                "Brown ground beef in a skillet over medium-high heat.",
                "Add taco seasoning and water, simmer until thickened.",
                "Warm taco shells in the oven for 3 minutes.",
                "Fill shells with seasoned beef.",
                "Top with shredded lettuce, diced tomato, cheese, and sour cream."
            ],
            Ratings = [4, 4, 5, 3]
        },
        new()
        {
            Id = 4,
            Title = "Pad Thai",
            Category = "Thai",
            Description = "Stir-fried rice noodles with shrimp, peanuts, and a tangy tamarind sauce.",
            Ingredients = ["Rice noodles", "Shrimp", "Eggs", "Bean sprouts", "Green onions", "Peanuts", "Tamarind paste", "Fish sauce", "Lime"],
            Steps =
            [
                "Soak rice noodles in warm water for 30 minutes, then drain.",
                "Mix tamarind paste, fish sauce, and sugar for the sauce.",
                "Stir-fry shrimp in a hot wok until pink, set aside.",
                "Scramble eggs in the wok, then add noodles and sauce.",
                "Toss until noodles are coated and tender.",
                "Add shrimp, bean sprouts, and green onions.",
                "Serve topped with crushed peanuts and lime wedges."
            ],
            Ratings = [5, 4, 5]
        },
        new()
        {
            Id = 5,
            Title = "Spaghetti Carbonara",
            Category = "Italian",
            Description = "Classic Roman pasta with eggs, pecorino cheese, guanciale, and black pepper.",
            Ingredients = ["Spaghetti", "Guanciale", "Eggs", "Pecorino Romano", "Black pepper"],
            Steps =
            [
                "Cook spaghetti in salted boiling water until al dente.",
                "Crisp guanciale in a cold pan over medium heat.",
                "Whisk eggs with grated pecorino and black pepper.",
                "Drain pasta, reserving some pasta water.",
                "Toss hot pasta with guanciale off the heat.",
                "Add egg mixture and toss quickly, adding pasta water for creaminess.",
                "Serve immediately with extra pecorino and pepper."
            ],
            Ratings = [5, 5, 5, 4, 5]
        },
        new()
        {
            Id = 6,
            Title = "Guacamole",
            Category = "Mexican",
            Description = "Fresh and vibrant avocado dip with lime, cilantro, and jalapeño.",
            Ingredients = ["Avocados", "Lime juice", "Cilantro", "Red onion", "Jalapeño", "Tomato", "Salt"],
            Steps =
            [
                "Halve avocados and remove pits.",
                "Mash avocado to desired consistency.",
                "Stir in diced onion, jalapeño, tomato, and cilantro.",
                "Add lime juice and salt to taste.",
                "Serve with tortilla chips."
            ],
            Ratings = [4, 5, 4, 4]
        }
    ];

    public IReadOnlyList<Recipe> GetAllRecipes() => _recipes.AsReadOnly();

    public IReadOnlyList<string> GetCategories() =>
        _recipes.Select(r => r.Category).Distinct().Order().ToList().AsReadOnly();

    public IReadOnlyList<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList().AsReadOnly();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRating(int recipeId, int rating)
    {
        var recipe = GetRecipeById(recipeId);
        if (recipe is not null && rating is >= 1 and <= 5)
        {
            recipe.Ratings.Add(rating);
        }
    }

    public void AddRecipe(Recipe recipe)
    {
        recipe.Id = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(recipe);
    }
}

@rendermode InteractiveServer

<div class="star-rating">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-thanks">Thanks for rating!</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public EventCallback<int> OnRated { get; set; }

    private int _selectedRating;
    private bool _submitted;

    private async Task Rate(int rating)
    {
        _selectedRating = rating;
        _submitted = true;
        await OnRated.InvokeAsync(rating);
    }
}

